const input = $input.first().json;
const p = input.body || input;
const tz = 'America/Mexico_City';
const now = new Date();
const todayCDMX = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
const requestId = String(p.request_id || p.message_id || p.id || `ci-${Date.now()}`);
const text = String(p.text || p.message || p.body || '').slice(0, 1200);
const history = Array.isArray(p.history) ? p.history.slice(-12) : [];
const accountContext = p.account_context && typeof p.account_context === 'object'
  ? p.account_context : null;
const conversationContext = p.conversation_context && typeof p.conversation_context === 'object'
  ? p.conversation_context : null;
const contextualText = String(
  conversationContext?.contextualText
    || [conversationContext?.previousQuestion, conversationContext?.currentReply]
      .filter(Boolean).join('\nRespuesta: ')
    || text
).slice(0, 1200);
const contact = {
  wa_number: p.wa_number || p.waNumber || p.account_wa_number || null,
  contact_number: p.contact_number || p.contactNumber || p.from || p.phone || null,
  name: p.contact_name || p.contactName || p.name || null,
  espo_id: p.espo_id || p.espoId || null,
  role: p.role || p.contact?.role || null
};
const accountInput = accountContext || p.account || {};
const projects = Array.isArray(accountContext?.projects) ? accountContext.projects : [];
const primaryProject = projects.find(project => project?.isDefault) || projects[0] || null;
const account = {
  name: accountInput.name || p.account_name || p.company || null,
  project: accountInput.project || primaryProject?.projectKey || p.project || p.project_name || null,
  project_slug: accountInput.project_slug || primaryProject?.projectKey || p.project_slug || null
};
const identityStatus = contact.espo_id ? 'known' : (contact.contact_number ? 'candidate' : 'unknown');
const context = {
  source: p.source || 'unknown',
  request_id: requestId,
  channel: p.channel || 'whatsapp',
  text,
  stage: p.stage || 'desconocido',
  history,
  contact,
  account,
  account_key: accountContext?.accountKey || p.account_key || null,
  account_context: accountContext,
  conversation_context: conversationContext,
  contextual_text: contextualText,
  project_slug: account.project_slug || account.project || 'ia360',
  dry_run: true,
  today_cdmx: todayCDMX,
  identity_status_seed: identityStatus,
  // --- P16 (19-ago-2026) -----------------------------------------------------
  // El tipo REAL del mensaje y su carga estructurada. Antes todo llegaba
  // aplanado a `text`: un tap de boton y alguien tecleando esa misma palabra
  // eran indistinguibles para el modelo, y las respuestas de Flow
  // (interactive.nfm_reply.response_json) no llegaban nunca.
  // `structured` NO es fuente de identidad: la tenencia se resuelve aguas
  // arriba y el modelo no puede elegirla desde aqui.
  message_type: p.message_type || 'text',
  structured: p.structured || null,
  contract_version: p.contract_version || 1,
  architecture_note: 'Draft agentic workflow: identity -> classification -> tools/RAG -> response contract. No sends or CRM writes from n8n.'
};
return [{ json: { ...context, agent_input: JSON.stringify(context, null, 2) } }];

const j = $input.first().json;
const seed = {
  identity_status: j.identity_status_seed || 'unknown',
  contact_number_present: !!(j.contact && j.contact.contact_number),
  espo_id_present: !!(j.contact && j.contact.espo_id),
  source: j.source,
  note: 'Draft snapshot only. Real lookup/write remains pending for ForgeChat/EspoCRM subworkflow.'
};
return [{ json: { ...j, identity_snapshot: seed } }];

const base = ($('Prepare RAG Pinecone Dry Run').first()?.json) || $('Lookup IA360 Memory').first().json || $('Identity Snapshot').first().json;
const memoryContext = base.memory_context || null;
const memorySeen = Boolean(memoryContext && (memoryContext.facts_count > 0 || memoryContext.events_count > 0 || memoryContext.schema === 'ia360_memory_context_for_agent.v1'));
const signalClassification = base.signal_classification || null;
const ragContext = base.rag_context || null;
const rawItem = $input.first().json;
const agentErrorCode = typeof rawItem?.error === 'string' && rawItem.error.trim()
  ? 'AGENT_PROVIDER_UNAVAILABLE' : null;
let candidate = rawItem.output ?? rawItem.text ?? rawItem;
if (typeof candidate === 'string') {
  const trimmed = candidate.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  try { candidate = JSON.parse(trimmed); } catch (e) { candidate = { reply: trimmed }; }
}
if (!candidate || typeof candidate !== 'object') candidate = {};
const allowedIntents = new Set(['book','ask_pain','provide_info','optout','smalltalk','other','list_bookings']);
const allowedActions = new Set(['offer_slots','book','cancel','reschedule','list_bookings','advance_pain','nurture','optout','none']);
const ci = candidate.contact_intelligence && typeof candidate.contact_intelligence === 'object' ? candidate.contact_intelligence : {};
const toolsUsed = Array.isArray(ci.tools_used) ? [...ci.tools_used] : [];
if (memorySeen && !toolsUsed.includes('ia360_memory_lookup')) toolsUsed.push('ia360_memory_lookup');
if (signalClassification && !toolsUsed.includes('ia360_signal_classifier_gpt_5_5')) toolsUsed.push('ia360_signal_classifier_gpt_5_5');
if (ragContext && !toolsUsed.includes('ia360_hybrid_rag')) toolsUsed.push('ia360_hybrid_rag');
const text = String(base.text || '').trim();
const lower = text.toLowerCase();
const ownerCommand = /\b(da de alta|alta a|agrega|registra|env[ií]ale|manda|pipeline|mueve|crm|whatsapp|wa)\b/i.test(lower);
const englishLeak = /\b(currently|however|let'?s|can'?t|cannot|workflow|assistance|further)\b/i.test(String(candidate.reply || ''));
function cleanText(value, max = 240) {
  return String(value || '')
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[email]')
    .replace(/\+?\d[\d\s().-]{7,}\d/g, '[phone]')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max);
}
function titleName(value) {
  if (!value) return null;
  return value.charAt(0).toUpperCase() + value.slice(1).toLowerCase();
}
let targetName = null;
const nameMatch = lower.match(/(?:da de alta a|alta a|agrega a|registra a|env[ií]ale a)\s+([a-záéíóúñ]+)/i);
if (nameMatch) targetName = titleName(nameMatch[1]);
let reply = String(candidate.reply || 'Te leo. Para cuidarlo bien, lo dejo como revisión de Alek antes de responder automático.').slice(0, 600);
let intent = allowedIntents.has(candidate.intent) ? candidate.intent : 'other';
let action = allowedActions.has(candidate.action) ? candidate.action : 'none';
if (ownerCommand && (englishLeak || intent === 'other' || action === 'none')) {
  const who = targetName || 'ese contacto';
  reply = `Listo, lo preparo. Para dar de alta a ${who} necesito su número de WhatsApp y confirmar qué pipeline quieres enviar. Pásamelo y lo dejo listo para revisión antes de enviarlo.`;
  intent = 'provide_info';
  action = 'nurture';
  ci.route = 'human_review';
  ci.next_best_action = `Pedir número de WhatsApp y pipeline para ${who}; preparar alta/envío con revisión humana.`;
  ci.human_review_required = true;
  ci.confidence = Math.max(typeof ci.confidence === 'number' ? ci.confidence : 0, 0.85);
}
if (englishLeak && !ownerCommand) {
  reply = 'Lo dejo en revisión con Alek para responder bien en español y no ejecutar nada sensible sin confirmación.';
  intent = intent === 'smalltalk' ? 'smalltalk' : 'other';
  action = action === 'offer_slots' ? action : 'none';
  ci.route = ci.route || 'human_review';
  ci.human_review_required = true;
}
function corta(v, max) {
  const s = cleanText(v, max * 2);
  if (s.length <= max) return s;
  const t = s.slice(0, max);
  const sp = t.lastIndexOf(' ');
  return (sp > max * 0.5 ? t.slice(0, sp) : t).replace(/[,;:.\s]+$/, '');
}
function humano(v, max) {
  const s = corta(v, max);
  return s ? s.charAt(0).toUpperCase() + s.slice(1) : '';
}
function preguntaUtil(md) {
  const s = corta(md, 90);
  return s ? `Para no darte vueltas: ¿me confirmas ${s.charAt(0).toLowerCase() + s.slice(1)}?`
           : '¿Qué parte te está frenando más ahora?';
}
const contactName = String(base.contact?.name || '').toLowerCase();
const accountName = String(base.account?.name || '').toLowerCase();
const activeClient = /andr[eé]s|camiones|cliente activo|cfo|champion|beta/.test(`${contactName} ${accountName} ${lower}`);
const agendaPush = /\b(agenda|agendar|reuni[oó]n|calendario|horario|cita)\b/i.test(reply);
const askedAgenda = /\b(agenda|agendar|reuni[oó]n|horario|cita|disponibilidad)\b/i.test(lower);
if (activeClient && agendaPush && !askedAgenda) {
  const res1 = humano(signalClassification?.summary, 150);
  reply = [res1 || 'Te leo', preguntaUtil(signalClassification?.missing_data)].join('. ');
  intent = 'ask_pain';
  action = 'advance_pain';
  ci.route = 'diagnostico';
  ci.next_best_action = signalClassification?.next_action || 'Responder con hallazgo, dato mínimo faltante y siguiente acción.';
}
if (activeClient && (!reply || reply.length < 30)) {
  const res2 = humano(signalClassification?.summary, 150);
  reply = res2 ? [res2, preguntaUtil(signalClassification?.missing_data)].join('. ')
               : preguntaUtil(signalClassification?.missing_data);
  intent = intent === 'smalltalk' ? 'ask_pain' : intent;
  action = action === 'none' ? 'advance_pain' : action;
  ci.route = ci.route === 'no_action' ? 'diagnostico' : (ci.route || 'diagnostico');
}
const confidence = typeof ci.confidence === 'number' ? Math.max(0, Math.min(1, ci.confidence)) : (signalClassification?.confidence ?? 0.5);
const guardrails = {
  external_send_allowed: false,
  whatsapp_send_executed: false,
  crm_write_executed: false,
  transcript_returned: false,
  rag_production_query: true,
};
const auditContact = {
  masked_contact_number: base.contact_key || maskNumber(base.contact?.contact_number || base.contact?.wa_id || base.contact?.phone),
  name: cleanText(base.contact?.name || '', 120) || null,
  role: cleanText(base.contact?.role || '', 120) || null,
  espo_contact_id: base.contact?.espo_id || base.contact?.espo_contact_id || null,
};
if (!reply || !String(reply).trim()) {
  const quien = cleanText(base.contact?.name || '', 40).split(' ')[0];
  const pista = humano(signalClassification?.summary, 140);
  reply = pista
    ? `${quien ? quien + ', ' : ''}sobre lo que me dices: ${pista.charAt(0).toLowerCase() + pista.slice(1)}. ${preguntaUtil(signalClassification?.missing_data)}`
    : `${quien ? quien + ', ' : ''}te leo. Dime en una linea que necesitas exactamente y te lo resuelvo o te digo quien lo tiene.`;
}
const out = {
  reply: reply.slice(0, 600),
  intent,
  date: /^\d{4}-\d{2}-\d{2}$/.test(String(candidate.date || '')) ? String(candidate.date) : null,
  action,
  extracted: candidate.extracted && typeof candidate.extracted === 'object' ? candidate.extracted : {},
  source: 'ia360-contact-intelligence-agent-draft',
  agent_error_code: agentErrorCode,
  account_context: base.account_context || null,
  conversation_context: base.conversation_context || null,
  contextual_text: base.contextual_text || base.text || '',
  contact_intelligence: {
    identity_status: ci.identity_status || base.identity_snapshot?.identity_status || 'unknown',
    route: ci.route || 'human_review',
    stage_signal: ci.stage_signal || base.stage || 'desconocido',
    tools_used: toolsUsed,
    confidence,
    next_best_action: ci.next_best_action || signalClassification?.next_action || 'Auditar en WhatsApp/n8n antes de activar egress.',
    human_review_required: ci.human_review_required !== false || Boolean(signalClassification?.owner_review_required),
  },
  dry_run: true,
  requires_human_approval: true,
  memory_context: memoryContext,
  signal_classification: signalClassification,
  rag_context: ragContext,
  audit: {
    request_id: base.request_id,
    channel: base.channel,
    contact: auditContact,
    identity_snapshot: base.identity_snapshot,
    memory_context: memoryContext,
    signal_classification: signalClassification,
    rag_context: ragContext,
  },
};
return [{ json: out }];

