const contactNumber = $fromAI('contact_number', 'Numero de WhatsApp del contacto si esta disponible', 'string');
const espoId = $fromAI('espo_id', 'ID EspoCRM si ya existe', 'string');
return JSON.stringify({ ok: true, mode: 'draft', identity_status: espoId ? 'known' : (contactNumber ? 'candidate' : 'unknown'), contact_number_present: !!contactNumber, espo_id_present: !!espoId, note: 'No escribe datos. En la siguiente iteracion este tool consulta ForgeChat/EspoCRM.' });

const j = $input.first().json;
const baseUrl = String($env.FORGECHAT_API_BASE_URL || 'https://wa.geekstudio.dev').replace(/\/$/, '');
const secret = $env.IA360_DIRECTIVE_SECRET || '';

async function lookupMemory(contact) {
  const guardrails = {
    transcript_returned: false,
    external_send_allowed: false,
    crm_write_executed: false
  };
  if (!secret) {
    return { ok: false, error: 'missing_IA360_DIRECTIVE_SECRET', events: [], facts: [], guardrails };
  }
  if (!contact?.wa_number || !contact?.contact_number) {
    return { ok: false, error: 'missing_contact_keys', events: [], facts: [], guardrails };
  }
  const payload = {
    wa_number: contact.wa_number,
    contact_number: contact.contact_number,
    limit: 8
  };
  if (this?.helpers?.httpRequest) {
    return await this.helpers.httpRequest({
      method: 'POST',
      url: `${baseUrl}/api/internal/ia360-memory/lookup`,
      headers: {
        'content-type': 'application/json',
        'X-IA360-Directive-Secret': secret
      },
      body: payload,
      json: true
    });
  }
  if (typeof fetch !== 'function') {
    return { ok: false, error: 'http_client_unavailable', events: [], facts: [], guardrails };
  }
  const res = await fetch(`${baseUrl}/api/internal/ia360-memory/lookup`, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'X-IA360-Directive-Secret': secret
    },
    body: JSON.stringify(payload)
  });
  const data = await res.json().catch(() => ({}));
  return { ...data, ok: Boolean(data.ok) && res.ok };
}

const memory = await lookupMemory.call(this, j.contact || {});
const memoryFacts = Array.isArray(memory.facts) ? memory.facts.slice(0, 5) : [];
const memoryEvents = Array.isArray(memory.events) ? memory.events.slice(0, 5) : [];
const memorySummary = [
  ...memoryFacts.map(f => ({
    type: 'fact',
    persona: f.persona || null,
    role: f.role || null,
    preference: f.preference || null,
    recurring_pain: f.recurring_pain || null,
    affected_process: f.affected_process || null,
    missing_metric: f.missing_metric || null,
    confidence: f.confidence || null,
    status: f.status || null
  })),
  ...memoryEvents.map(e => ({
    type: 'event',
    area: e.area || null,
    signal_type: e.signal_type || null,
    summary: e.summary || null,
    business_impact: e.business_impact || null,
    missing_data: e.missing_data || null,
    next_action: e.next_action || null,
    owner_review_status: e.owner_review_status || null
  }))
];

const memoryContext = {
  schema: 'ia360_memory_context_for_agent.v1',
  ok: Boolean(memory.ok),
  facts_count: memoryFacts.length,
  events_count: memoryEvents.length,
  summary: memorySummary,
  lookup_error: memory.ok ? null : (memory.error || null),
  guardrails: {
    transcript_returned: false,
    external_send_allowed: false,
    crm_write_executed: false
  }
};

const agentPayload = {
  ...j,
  memory_context: memoryContext,
  instruction: 'Antes de responder, usa memory_context si trae facts o events. No inventes datos. No copies transcript. Si hay señal útil, responde con hallazgo, impacto, dato faltante y siguiente acción. En contact_intelligence.tools_used incluye ia360_memory_lookup cuando este contexto exista.'
};

return [{
  json: {
    ...j,
    memory_context: memoryContext,
    agent_input: JSON.stringify(agentPayload, null, 2)
  }
}];

const gw = $('ia360-context-gateway').first().json;
const norm = $('Normalize WhatsApp Context').first().json;
const mem = $('Lookup IA360 Memory').all().map(i => i.json);
const surfaces = $('coexistence.ia360_product_surfaces').all().map(i => i.json);

// Modos de contacto y directivas dinámicas
const operatingMode = gw.operating_mode || 'standard';
let modeDirectives = '';

if (operatingMode === 'sesion_presencial' || gw.is_in_presencial_session) {
  modeDirectives = `
MODO ACTIVO: SESIÓN PRESENCIAL EN VIVO (Alek y el cliente están juntos en persona).
REGLAS OBLIGATORIAS:
1. PROHIBIDO presentarse o re-saludar ("Soy Alekito...", "¡Qué onda!"). Ve directo a responder o tomar nota.
2. PROHIBIDO pitches comerciales, encuestas de dolor o pedir agendar llamadas.
3. Actúa como copiloto técnico y asistente de bitácora: respuestas concisas al grano y registro de requerimientos o notas de campo.`;
} else if (operatingMode === 'silencio_humano' || gw.is_human_silenced) {
  modeDirectives = `
MODO ACTIVO: SILENCIO HUMANO.
Alek está atendiendo directamente la conversación. No generes respuestas salientes automáticas redundantes.`;
} else if (operatingMode === 'champion_operativo' || gw.rol === 'champion') {
  modeDirectives = `
MODO ACTIVO: CHAMPION OPERATIVO / CLIENTE ACTIVO.
REGLAS:
1. Habla en lenguaje de negocio del cliente (Field Service, órdenes de trabajo, catálogo, soporte, instalaciones).
2. PROHIBIDO enviar encuestas de dolor, cotizaciones o embudos de ventas.`;
} else if (operatingMode === 'soporte_tecnico') {
  modeDirectives = `
MODO ACTIVO: SOPORTE TÉCNICO E INFRAESTRUCTURA.
Enfócate en asistencia paso a paso sobre servidores, credenciales, Bitwarden, SSH, Docker y despliegues.`;
}

// Inyección de hechos de ChromaDB
const hybridRagSnippets = [];
if (mem && mem.length > 0) {
  for (const m of mem) {
    if (m.fact_key) {
      hybridRagSnippets.push({
        id: `fact_${m.id || m.fact_key}`,
        text: `[${m.account_key || gw.account_key}] ${m.role ? m.role + ': ' : ''}${m.preference || ''} ${m.recurring_pain || ''}`.trim(),
        metadata: {
          account_key: m.account_key || gw.account_key,
          persona: m.persona,
          role: m.role,
          status: m.status
        }
      });
    }
  }
}

// Inyección de superficies verificadas
const verifiedSurfaces = [];
if (surfaces && surfaces.length > 0) {
  for (const s of surfaces) {
    if (s.surface_key && s.active !== false) {
      verifiedSurfaces.push({
        surface_key: s.surface_key,
        project_key: s.project_key,
        canonical_origin: s.canonical_origin,
        path_prefix: s.path_prefix,
        auth_mode: s.auth_mode
      });
    }
  }
}

const ragContext = {
  schema: 'ia360_hybrid_rag.v2',
  engine: 'chroma_local + ollama_nomic_embed',
  account_key: gw.account_key,
  active_project: gw.active_project,
  operating_mode: operatingMode,
  mode_expires_at: gw.mode_expires_at,
  mode_directives: modeDirectives,
  snippets: hybridRagSnippets,
  verified_surfaces: verifiedSurfaces
};

return [{
  json: {
    rag_context: ragContext,
    account_key: gw.account_key,
    active_project: gw.active_project,
    operating_mode: operatingMode,
    mode_directives: modeDirectives,
    verified_surfaces: verifiedSurfaces,
    hybrid_rag_snippets: hybridRagSnippets
  }
}];
